INSERT INTO data_change_histories (
    target_business, target_key, change_type, field_name,
    before_value, after_value, changed_by, change_reason, request_id
)
VALUES (
    'education_achievements', #{id}, #{action}, 'aggregate',
    #{before}, #{after}, #{userId}, '취업률 제고 실적 저장', #{requestId}
)

INSERT INTO education_achievement_status_histories (
    achievement_type, achievement_id, previous_status, next_status, action_type, processed_by, request_id
)
VALUES (
    'EMPLOYMENT_RATE_IMPROVEMENT', #{id}, #{previous}, #{next},
    CASE WHEN #{previous}::varchar IS NULL THEN 'CREATE' ELSE 'SUBMIT' END, #{userId}, #{requestId}
)
